    riverside_districts = {}
    for row in reader:
        if 'Riverside' in row.get('District Name', '') or 'Riverside' in row.get('County Name', ''):
            ds = row.get('District Name')
            cds = row.get('CDSCode')
            if ds and cds:
                if ds not in riverside_districts:
                    riverside_districts[ds] = []
                riverside_districts[ds].append((cds, row.get('Charter Funding Type', '')))
    print(f'Total unique Riverside districts: {len(riverside_districts)}')
    for ds, entries in list(riverside_districts.items())[:5]:
        print(f'District: {ds}')
